// Loft cooling fan with hysteresis and a boost button.
// TMP-style linear probe on A3 (10 mV/°C), fan on D5, boost on D4.

const int TEMP_PIN = A3;
const int FAN_PIN = 5;
const int BOOST_PIN = 4;

const float ON_C = 36.0f;
const float OFF_C = 32.0f;
const float MV_PER_C = 10.0f;
const unsigned long SAMPLE_MS = 50;
const unsigned long LOG_MS = 1000;
const unsigned long TEMP_CONFIRM_MS = 400;
const unsigned long BOOST_DEBOUNCE_MS = 20;

bool fanOn = false;
bool onPending = false;
bool offPending = false;
unsigned long onSince = 0;
unsigned long offSince = 0;
bool boostRaw = false;
bool boostStable = false;
unsigned long boostChangeAt = 0;
unsigned long lastSample = 0;
unsigned long lastLog = 0;
float tempC = 0.0f;

float sampleTempC()
{
    int raw = analogRead(TEMP_PIN);
    float mv = raw * (5000.0f / 1023.0f);
    return mv / MV_PER_C;
}

void driveFan(bool on)
{
    fanOn = on;
    digitalWrite(FAN_PIN, on ? HIGH : LOW);
}

void logLine()
{
    Serial.print("loft: ");
    Serial.print(tempC, 1);
    Serial.print(" C fan=");
    Serial.println(fanOn ? "ON" : "OFF");
}

void setup()
{
    pinMode(FAN_PIN, OUTPUT);
    pinMode(BOOST_PIN, INPUT_PULLUP);
    digitalWrite(FAN_PIN, LOW);
    Serial.begin(9600);
    lastSample = millis();
    lastLog = millis();
    boostRaw = (digitalRead(BOOST_PIN) == LOW);
    boostStable = boostRaw;
    boostChangeAt = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastSample >= SAMPLE_MS)
    {
        lastSample = now;
        tempC = sampleTempC();

        bool raw = (digitalRead(BOOST_PIN) == LOW);
        if (raw != boostRaw)
        {
            boostRaw = raw;
            boostChangeAt = now;
        }
        if (boostRaw != boostStable && (now - boostChangeAt) >= BOOST_DEBOUNCE_MS)
        {
            boostStable = boostRaw;
        }

        if (boostStable)
        {
            onPending = false;
            offPending = false;
            driveFan(true);
        }
        else
        {
            if (tempC >= ON_C)
            {
                if (!onPending)
                {
                    onPending = true;
                    onSince = now;
                }
            }
            else
            {
                onPending = false;
            }
            if (tempC <= OFF_C)
            {
                if (!offPending)
                {
                    offPending = true;
                    offSince = now;
                }
            }
            else
            {
                offPending = false;
            }

            if (onPending && (now - onSince) >= TEMP_CONFIRM_MS)
            {
                driveFan(true);
            }
            else if (offPending && (now - offSince) >= TEMP_CONFIRM_MS)
            {
                driveFan(false);
            }
        }
    }

    if (now - lastLog >= LOG_MS)
    {
        lastLog = now;
        logLine();
    }
}

// Basement sump controller.
// Ultrasonic level proxy as linear voltage on A1, pump contactor on D7,
// silence button on D4 (active LOW, pull-up).

const uint8_t LEVEL_PIN = A1;
const uint8_t PUMP_PIN = 7;
const uint8_t SILENCE_PIN = 4;

const float START_CM = 45.0f;
const float STOP_CM = 30.0f;
const float MV_PER_CM = 10.0f;
const unsigned long POLL_MS = 40;
const unsigned long LOG_MS = 800;
const unsigned long CONFIRM_MS = 300;

bool pumpOn = false;
bool silenceLatched = false;
unsigned long lastPoll = 0;
unsigned long lastLog = 0;
float levelCm = 0.0f;

// Pending state change confirmation.
bool pendingValid = false;
bool pendingState = false;
unsigned long pendingSince = 0;

float sampleLevelCm()
{
    int adc = analogRead(LEVEL_PIN);
    float mv = adc * (5000.0f / 1023.0f);
    return mv / MV_PER_CM;
}

void setPump(bool on)
{
    pumpOn = on;
    digitalWrite(PUMP_PIN, on ? HIGH : LOW);
}

void emitLog()
{
    Serial.print("sump cm=");
    Serial.print(levelCm, 1);
    Serial.print(" pump=");
    Serial.print(pumpOn ? 1 : 0);
    Serial.print(" mute=");
    Serial.println(silenceLatched ? 1 : 0);
}

void setup()
{
    pinMode(PUMP_PIN, OUTPUT);
    pinMode(SILENCE_PIN, INPUT_PULLUP);
    digitalWrite(PUMP_PIN, LOW);
    Serial.begin(9600);
    lastPoll = millis();
    lastLog = millis();
}

void loop()
{
    unsigned long t = millis();

    if (digitalRead(SILENCE_PIN) == LOW)
    {
        silenceLatched = true;
        setPump(false);
        pendingValid = false;
    }

    if (t - lastPoll >= POLL_MS)
    {
        lastPoll = t;
        levelCm = sampleLevelCm();

        if (!silenceLatched)
        {
            // Hysteresis: start at START_CM, stop at STOP_CM.
            bool want = pumpOn;
            if (!pumpOn && levelCm >= START_CM)
            {
                want = true;
            }
            else if (pumpOn && levelCm <= STOP_CM)
            {
                want = false;
            }

            if (want != pumpOn)
            {
                // Require the new state to hold continuously before switching.
                if (!pendingValid || pendingState != want)
                {
                    pendingValid = true;
                    pendingState = want;
                    pendingSince = t;
                }
                else if (t - pendingSince >= CONFIRM_MS)
                {
                    setPump(want);
                    pendingValid = false;
                }
            }
            else
            {
                pendingValid = false;
            }
        }
    }

    if (t - lastLog >= LOG_MS)
    {
        lastLog = t;
        emitLog();
    }
}

// Harbor nav beacon: 500 ms on / 500 ms off on D12.
// Quiet mode switch on D3 (pull-up). Status over UART.

const int BEACON_PIN = 12;
const int QUIET_PIN = 3;
const byte HALF_MS = 500;
const unsigned long STATUS_MS = 2000;
const unsigned long QUIET_DEBOUNCE_MS = 40;

bool lampOn = false;
unsigned long lastSlice = 0;
unsigned long lastStatus = 0;
unsigned long risingCount = 0;
bool quietHeld = false;
bool quietRaw = false;
unsigned long quietChangeMs = 0;

void setBeacon(bool on)
{
    lampOn = on;
    digitalWrite(BEACON_PIN, on ? HIGH : LOW);
}

void emitTick()
{
    Serial.println("tick");
    risingCount++;
}

void publishStatus()
{
    Serial.print("nav rises=");
    Serial.print(risingCount);
    Serial.print(" quiet=");
    Serial.println(quietHeld ? 1 : 0);
}

bool readQuiet()
{
    return digitalRead(QUIET_PIN) == LOW;
}

void setup()
{
    pinMode(BEACON_PIN, OUTPUT);
    pinMode(QUIET_PIN, INPUT_PULLUP);
    setBeacon(false);
    Serial.begin(9600);
    lastSlice = millis();
    lastStatus = millis();
    quietRaw = readQuiet();
    quietHeld = quietRaw;
    quietChangeMs = millis();
}

void loop()
{
    unsigned long now = millis();

    bool raw = readQuiet();
    if (raw != quietRaw)
    {
        quietRaw = raw;
        quietChangeMs = now;
    }
    if (quietRaw != quietHeld && (now - quietChangeMs) >= QUIET_DEBOUNCE_MS)
    {
        quietHeld = quietRaw;
    }

    if (quietHeld)
    {
        setBeacon(false);
        lastSlice = now;
    }
    else if ((now - lastSlice) >= HALF_MS)
    {
        lastSlice = now;
        bool nextOn = !lampOn;
        setBeacon(nextOn);
        if (nextOn)
        {
            emitTick();
        }
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        publishStatus();
    }
}
